<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { ApiError, request } from '../api'
import { modelChoice } from '../helpers'
import { intakeLabels, type Intake, type Risk, type TaskGoal, type TaskJob, type TaskStatus, type Visit } from '../types'
import SourceCard from './SourceCard.vue'

const props = defineProps<{ visitId: string; modelAvailable: boolean; dirty: boolean; busy: boolean; currentRisk?: Risk | null }>()
const emit = defineEmits<{ close: []; saveDraft: []; applied: [visit: Visit]; navigate: [section: 'prepare' | 'chat' | 'timeline'] }>()
const goals: { value: TaskGoal; title: string; detail: string; icon: string }[] = [
  { value: 'prepare_visit', title: '准备一次就诊', detail: '整理已有自述、待补信息和随身准备材料。', icon: '▤' },
  { value: 'understand_symptom', title: '查阅对应资料', detail: '查找与已描述不适有关的资料，核对原文证据。', icon: '⌕' },
  { value: 'organize_timeline', title: '梳理变化时间线', detail: '按记录时间整理本人观察，不解释测量数值。', icon: '◷' },
]
const selectedGoal = ref<TaskGoal>('prepare_visit')
const usePlannerModel = ref(false)
const jobs = ref<TaskJob[]>([])
const selected = ref<TaskJob | null>(null)
const loading = ref(false)
const starting = ref(false)
const applying = ref(false)
const confirming = ref(false)
const error = ref('')
const notice = ref('')
const confirmationBox = ref<HTMLElement | null>(null)
const readVersions = new Map<string, number>()
let contextVersion = 0
let disposed = false
let pollTimer: ReturnType<typeof setTimeout> | undefined
const statusLabels: Record<TaskStatus, string> = { queued: '已排队', running: '正在执行', completed: '执行完成', needs_input: '需要补充信息', emergency: '当前安全提醒优先', failed: '执行未完成', interrupted: '运行已中断', superseded: '结果已过期' }
const stepLabels = { pending: '未执行', running: '执行中', done: '完成', failed: '未完成', skipped: '已跳过' }
const pendingJob = computed(() => jobs.value.find(job => pending(job)))
const result = computed(() => selected.value?.result || null)
const displayStatus = computed(() => props.currentRisk?.level === 'emergency' ? 'emergency' : selected.value?.status || 'queued')
const locked = computed(() => props.busy || loading.value || starting.value || applying.value)
const canApply = computed(() => props.currentRisk?.level !== 'emergency' && !!selected.value && selected.value.can_apply !== false && ['completed', 'needs_input'].includes(selected.value.status) && !!result.value?.summary && !selected.value.applied_at)
const plannerLabel = computed(() => ({ local: '本机规则规划', model: 'DeepSeek 规划', fallback: '本机回退规划' }[result.value?.plan.planner_mode || 'local']))
const plannerErrorLabel = computed(() => ({ unavailable: '外部规划服务不可用', timeout: '外部规划等待超时', network_error: '外部规划连接失败', invalid_plan: '外部计划未通过检查' }[result.value?.planner_error || 'unavailable']))

function pending(job: TaskJob): boolean { return ['queued', 'running'].includes(job.status) }
function taskTitle(goal: TaskGoal): string { return goals.find(item => item.value === goal)?.title || '准备任务' }
function fieldLabel(field: string): string { return intakeLabels[field as keyof Intake] || field }
function stepLabel(id: string): string { return result.value?.plan.steps.find(step => step.id === id)?.label || id }
function stamp(value: string): string { const date = new Date(value); return Number.isNaN(date.getTime()) ? '时间未记录' : date.toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }) }
function outputText(output: Record<string, unknown>): string { try { return JSON.stringify(output, null, 2) } catch { return '本步输出暂时无法读取。' } }
function validContext(version: number, visitId: string): boolean { return !disposed && version === contextVersion && visitId === props.visitId }
function checkJob(job: TaskJob): TaskJob {
  if (!job || !job.id || job.visit_id !== props.visitId || !(job.status in statusLabels)) throw new ApiError('任务返回的记录不完整，请重新加载。')
  if (['completed', 'needs_input'].includes(job.status) && (!job.result || !job.result.plan || !Array.isArray(job.result.plan.steps) || !Array.isArray(job.result.steps) || typeof job.result.content !== 'string' || !job.result.content.trim())) throw new ApiError('任务已经结束，但完整结果没有读到，请重新加载。')
  return job
}
function updateJob(job: TaskJob): void { const index = jobs.value.findIndex(item => item.id === job.id); if (index < 0) jobs.value.unshift(job); else jobs.value.splice(index, 1, job); if (selected.value?.id === job.id) selected.value = job }
function stopPolling(): void { if (pollTimer !== undefined) clearTimeout(pollTimer); pollTimer = undefined }
function schedulePoll(id: string, version: number): void { stopPolling(); pollTimer = setTimeout(() => { void readJob(id, version) }, 800) }
async function readJob(id: string, version = contextVersion): Promise<void> {
  const visitId = props.visitId
  const readVersion = (readVersions.get(id) || 0) + 1
  readVersions.set(id, readVersion)
  try {
    const job = await request<TaskJob>(`/api/visits/${encodeURIComponent(visitId)}/tasks/${encodeURIComponent(id)}`)
    if (!validContext(version, visitId) || readVersions.get(id) !== readVersion) return
    updateJob(checkJob(job))
    if (pendingJob.value) schedulePoll(pendingJob.value.id, version); else stopPolling()
  } catch (caught) { if (validContext(version, visitId) && readVersions.get(id) === readVersion) { stopPolling(); error.value = `任务状态暂时无法读取。${caught instanceof Error ? caught.message : '请重新加载。'}` } }
}
async function loadHistory(): Promise<void> {
  const version = ++contextVersion
  const visitId = props.visitId
  stopPolling(); loading.value = true; error.value = ''; confirming.value = false; notice.value = ''; jobs.value = []; selected.value = null
  try {
    const data = await request<{ items: TaskJob[] }>(`/api/visits/${encodeURIComponent(visitId)}/tasks`)
    if (!validContext(version, visitId)) return
    if (!Array.isArray(data.items)) throw new ApiError('任务历史返回的内容不完整，请重新加载。')
    jobs.value = data.items.map(checkJob)
    selected.value = pendingJob.value || jobs.value[0] || null
    if (pendingJob.value) schedulePoll(pendingJob.value.id, version)
  } catch (caught) { if (validContext(version, visitId)) error.value = caught instanceof Error ? caught.message : '任务历史没有加载完成，请重试。' }
  finally { if (validContext(version, visitId)) loading.value = false }
}
async function startTask(): Promise<void> {
  if (locked.value || pendingJob.value || !props.visitId) return
  const version = contextVersion
  const visitId = props.visitId
  starting.value = true; error.value = ''; notice.value = ''; confirming.value = false
  try {
    const data = await request<{ task: TaskJob }>(`/api/visits/${encodeURIComponent(visitId)}/tasks`, 'POST', { goal: selectedGoal.value, use_model: modelChoice(usePlannerModel.value, props.modelAvailable) })
    if (!validContext(version, visitId)) return
    const job = checkJob(data.task); updateJob(job); selected.value = job
    if (pending(job)) schedulePoll(job.id, version)
  } catch (caught) { if (validContext(version, visitId)) error.value = caught instanceof Error ? caught.message : '任务没有启动，请重试。' }
  finally { if (validContext(version, visitId)) starting.value = false }
}
function selectJob(job: TaskJob): void { selected.value = job; confirming.value = false; notice.value = ''; if (pending(job)) schedulePoll(job.id, contextVersion) }
function reviewResult(): void { confirming.value = true; error.value = ''; void nextTick(() => confirmationBox.value?.focus()) }
async function retryRead(): Promise<void> { error.value = ''; if (selected.value) await readJob(selected.value.id); else await loadHistory() }
async function applyResult(): Promise<void> {
  if (!canApply.value || locked.value || !selected.value || !confirming.value) return
  const version = contextVersion
  const visitId = props.visitId
  const jobId = selected.value.id
  applying.value = true; error.value = ''
  try {
    const data = await request<{ task: TaskJob; visit: Visit }>(`/api/visits/${encodeURIComponent(visitId)}/tasks/${encodeURIComponent(jobId)}/apply`, 'POST', {})
    if (!validContext(version, visitId)) return
    if (!data.visit || data.visit.id !== visitId || !data.task?.applied_at) throw new ApiError('保存结果没有返回完整确认，请重新加载任务。')
    updateJob(checkJob(data.task)); selected.value = data.task; confirming.value = false
    emit('applied', data.visit); notice.value = '准备结果已保存。本人信息与未保存草稿仍保留，请核对后使用。'
  } catch (caught) { if (validContext(version, visitId)) error.value = caught instanceof Error ? caught.message : '准备结果没有保存，请重新运行或重试。' }
  finally { if (validContext(version, visitId)) applying.value = false }
}
watch(() => props.visitId, () => { usePlannerModel.value = false; starting.value = false; applying.value = false; void loadHistory() }, { immediate: true })
onBeforeUnmount(() => { disposed = true; contextVersion++; stopPolling() })
</script>

<template>
  <div class="task-agent-panel">
    <header class="task-heading"><div><span>目标 → 规划 → 工具 → 核对</span><h2>让准备任务一步步完成</h2><p>选择一个目标，查看实际计划、执行记录和原文证据。结果先作为草稿，保存由你确认。</p></div><button class="task-return" :disabled="applying" @click="emit('close')">返回工作区 <span aria-hidden="true">↗</span></button></header>
    <div v-if="dirty" class="task-draft-note"><p><strong>当前还有未保存草稿</strong>本次任务使用已保存资料，草稿尚未加入。</p><button :disabled="locked" @click="emit('saveDraft')">先保存草稿</button></div>
    <fieldset class="task-goals" :disabled="locked || !!pendingJob"><legend>这次想完成什么？</legend><label v-for="goal in goals" :key="goal.value" :class="{ chosen: selectedGoal === goal.value }"><input v-model="selectedGoal" type="radio" name="agent-goal" :value="goal.value" /><span aria-hidden="true">{{ goal.icon }}</span><div><strong>{{ goal.title }}</strong><small>{{ goal.detail }}</small></div></label></fieldset>
    <div class="task-launch-row"><label class="task-model-choice"><input v-model="usePlannerModel" type="checkbox" :disabled="!modelAvailable || locked || !!pendingJob" /><span><strong>允许 DeepSeek 协助规划</strong><small>{{ modelAvailable ? '默认关闭。仅发送所选目标和哪些字段已填写，不发送自述原文。' : '外部规划未配置，使用本机规则。' }}</small></span></label><button class="primary-button task-start" :disabled="locked || !!pendingJob" @click="startTask">{{ starting ? '正在启动…' : pendingJob ? '已有任务正在运行' : '开始执行任务' }} <span aria-hidden="true">→</span></button></div>
    <div v-if="error" class="task-error" role="alert"><p>{{ error }}</p><button :disabled="locked" @click="retryRead">重新读取任务</button></div><p v-if="notice" class="task-notice" role="status">{{ notice }}</p>
    <p v-if="loading" class="task-loading" role="status"><span class="spinner" aria-hidden="true"></span>正在读取本条就诊记录的任务…</p>
    <div v-if="jobs.length" class="task-history"><span>本记录的任务</span><div><button v-for="job in jobs" :key="job.id" :class="{ selected: selected?.id === job.id }" :aria-pressed="selected?.id === job.id" @click="selectJob(job)"><strong>{{ taskTitle(job.goal) }}</strong><small>{{ stamp(job.created_at) }} · {{ job.applied_at ? '已保存结果' : statusLabels[job.status] }}</small></button></div></div>
    <div v-if="selected" class="task-current">
      <div v-if="currentRisk?.level === 'emergency'" class="task-risk" role="alert"><strong>先关注当前安全，暂停使用旧任务结果</strong><p>{{ currentRisk.message }}</p></div>
      <div class="task-status-row"><h3>{{ taskTitle(selected.goal) }}</h3><span :class="['task-state', `task-state-${displayStatus}`]">{{ statusLabels[displayStatus] }}</span></div>
      <div v-if="pending(selected)" class="task-running" role="status"><span class="spinner" aria-hidden="true"></span><div><strong>{{ selected.status === 'queued' ? '任务已排队，等待执行器开始。' : '执行器正在运行本次任务。' }}</strong><p>尚未返回执行结果；计划和步骤将在结果生成后展示。关闭面板后任务继续，可从本记录重新打开。</p></div></div>
      <div v-if="selected.error" class="task-error" role="alert">{{ selected.error }}</div>
      <div v-if="selected.invalidated_reason" class="task-error" role="alert">{{ selected.invalidated_reason }}<p v-if="selected.current_risk?.level === 'emergency'">{{ selected.current_risk.message }}</p></div>
      <p v-if="selected.status === 'interrupted'" class="task-boundary">运行已经中断。可重新启动任务；本次未自动保存准备资料。</p>
      <template v-if="result">
        <section v-if="result.risk.level !== 'unknown'" :class="['task-risk', { emergency: result.risk.level === 'emergency' }]" role="alert"><strong>{{ result.risk.level === 'emergency' ? '紧急提醒优先' : '需要留意的提醒' }}</strong><p>{{ result.risk.message }}</p><small>提示不能覆盖全部紧急情况，不能据此排除疾病。</small></section>
        <section class="task-plan"><div><span class="task-caption">本次实际计划</span><span class="task-planner">{{ plannerLabel }}</span></div><h3>{{ result.plan.objective }}</h3><p v-if="result.planner_notice" class="task-fallback">{{ result.planner_notice }}<small v-if="result.planner_error">{{ plannerErrorLabel }}</small></p><ol><li v-for="step in result.plan.steps" :key="step.id"><span>{{ step.label || step.tool }}</span><small v-if="step.depends_on.length">依赖：{{ step.depends_on.map(stepLabel).join('、') }}</small><small v-else>无前置依赖</small></li></ol></section>
        <section class="task-steps"><h3>实际执行记录</h3><p class="task-caption">展示工具调用与返回状态，不展示模型隐式思维。</p><ol><li v-for="(step, index) in result.steps" :key="step.id" :class="`step-${step.status}`"><span class="task-step-number">{{ index + 1 }}</span><div><div class="task-step-title"><strong>{{ step.label || step.tool }}</strong><span>{{ stepLabels[step.status] }}</span></div><p class="task-step-meta">{{ step.executed_by === 'local_safety' ? '安全优先执行' : '工具执行器' }} · <code>{{ step.tool }}</code></p><p v-if="step.depends_on.length" class="task-step-meta">依据：{{ step.depends_on.map(stepLabel).join('、') }}</p><p v-if="step.error" class="task-step-error">{{ step.error }}</p><p v-if="step.source_ids.length" class="task-step-meta">返回 {{ step.source_ids.length }} 条来源记录</p><details v-if="Object.keys(step.output).length" class="task-output"><summary>查看本步工具输出</summary><pre>{{ outputText(step.output) }}</pre></details></div></li></ol><p v-if="!result.steps.length" class="task-boundary">本次尚无实际工具执行记录。</p></section>
        <section v-if="selected.status === 'needs_input' || result.missing_fields.length || result.next_question" class="task-missing"><h3>还需要你补充或核对</h3><p v-if="selected.status === 'needs_input'">资料尚未完整，本次材料是待核对草稿。</p><ul v-if="result.missing_fields.length"><li v-for="field in result.missing_fields" :key="field">{{ fieldLabel(field) }}</li></ul><p v-if="result.next_question" class="task-next-question">{{ result.next_question }}</p><button class="secondary-button" @click="emit('navigate', selected.goal === 'organize_timeline' ? 'timeline' : 'prepare')">{{ selected.goal === 'organize_timeline' ? '去补充变化记录' : '去补充本人信息' }} →</button></section>
        <section class="task-outcome"><h3>本次整理结果</h3><div class="task-result-content">{{ result.content }}</div><details v-if="result.summary" class="task-document"><summary>查看待保存的自述摘要</summary><div>{{ result.summary.text }}</div></details><details v-if="result.checklist.length" class="task-document"><summary>查看准备清单（{{ result.checklist.length }} 项）</summary><ul><li v-for="item in result.checklist" :key="item.id">{{ item.text }}</li></ul></details><details v-if="result.preparation_plan" class="task-document"><summary>查看就诊沟通准备计划</summary><p>{{ result.preparation_plan.goal }}</p><ol><li v-for="question in result.preparation_plan.questions" :key="question">{{ question }}</li></ol><ul><li v-for="step in result.preparation_plan.steps" :key="step.id"><strong>{{ step.title }}</strong><p>{{ step.detail }}</p></li></ul><p>{{ result.preparation_plan.notice }}</p></details></section>
        <details v-if="result.evidence_ledger.length" class="task-evidence"><summary>核对本次证据 · {{ result.evidence_ledger.length }} 个原文片段</summary><p>只核对片段出处与原文是否对应，不代表医学判断已经核实。</p><article v-for="(clause, index) in result.evidence_ledger" :key="index"><div><span>{{ { source: '资料原文', self_report: '本人原话', safety_rule: '本机安全规则' }[clause.kind] }}</span><small>{{ clause.verified ? '原文片段已核对' : '片段待核对' }}</small></div><p>{{ clause.clause }}</p><blockquote>{{ clause.exact_span }}</blockquote><small>出处：{{ clause.reference }}<span v-if="clause.source_id"> · {{ clause.source_id }}</span></small><p v-if="clause.notice" class="task-evidence-notice">{{ clause.notice }}</p></article></details>
        <details v-if="result.sources.length" class="task-sources"><summary>查阅参考来源 · {{ result.sources.length }} 条资料</summary><SourceCard v-for="(source, index) in result.sources" :key="source.id" :source="source" :index="index" /></details>
        <section class="task-save"><p v-if="selected.applied_at" class="task-notice">本人已确认保存 · {{ stamp(selected.applied_at) }}</p><template v-else-if="canApply"><p>结果尚未保存。确认后，将更新本记录的摘要、准备清单与沟通计划。</p><button class="primary-button" :disabled="locked || !!pendingJob" @click="reviewResult">检查并保存准备结果</button><div v-if="confirming" ref="confirmationBox" class="task-apply-confirmation" tabindex="-1" role="alertdialog" aria-labelledby="task-apply-title"><h4 id="task-apply-title">确认保存这份准备材料？</h4><p>已有摘要、清单与准备计划将被替换。本人信息和未保存草稿会保留。</p><p v-if="selected.status === 'needs_input'" class="task-incomplete">这份材料尚未完整，请保留待补充标记，核对后再给医生使用。</p><p v-if="error" class="task-step-error" role="alert">{{ error }}</p><div><button class="secondary-button" :disabled="applying" @click="confirming = false">暂不保存</button><button class="primary-button" :disabled="locked" @click="applyResult">{{ applying ? '正在保存…' : '确认保存准备结果' }}</button></div></div></template><p v-else class="task-boundary">{{ selected.status === 'emergency' ? '紧急警示优先，本次结果不能保存为就诊准备材料。' : ['failed', 'interrupted'].includes(selected.status) ? '任务未完成，不能保存这次准备结果。' : '本次没有可保存的准备文档，可继续查阅结果或重新选择目标。' }}</p></section>
      </template>
    </div>
    <div v-else-if="!loading && !error" class="task-empty"><span aria-hidden="true">◇</span><h3>先选目标，再查看真实执行过程</h3><p>任务只读取已保存资料并草拟结果，不自动写入本人信息，不诊断或开药。</p></div>
  </div>
</template>

